B.afM={"Ascending aorta":0,"Arch of aorta":1,"Thoracic aorta":2,"Pulmonary trunk":3,"Right pulmonary artery":4,"Left pulmonary artery":5,"Right coronary artery":6,"Left coronary artery":7,"Internal thoracic artery":8,"Posterior intercostal arteries":9,"Common carotid artery":10,"Internal carotid artery (cervical part)":11,"External carotid artery":12,"Subclavian artery":13,"Vertebral artery":14,"Thyrocervical trunk":15,"Costocervical trunk":16,"Superior thyroid artery":17,"Lingual artery":18,"Facial artery":19,"Occipital artery":20,"Superficial temporal artery":21,"Maxillary artery":22,"Posterior auricular artery":23,"Supraorbital artery":24,"Supratrochlear artery":25,"Transverse facial artery":26,"Angular artery":27,[u.z]:28,"Vertebral artery (intracranial part)":29,"Basilar artery":30,"Posterior cerebral artery":31,"Middle cerebral artery":32,"Anterior cerebral artery":33,"Anterior communicating artery":34,"Posterior communicating artery":35,"Superior cerebellar artery":36,"Anterior inferior cerebellar artery":37,"Posterior inferior cerebellar artery":38,"Abdominal aorta":39,"Celiac trunk":40,"Left gastric artery":41,"Splenic artery":42,"Common hepatic artery":43,"Superior mesenteric artery":44,"Inferior mesenteric artery":45,"Renal artery":46,"Gonadal artery":47,"Common iliac artery":48,"Internal iliac artery":49,"External iliac artery":50,"Axillary artery":51,"Brachial artery":52,"Deep brachial artery (profunda brachii)":53,"Radial artery":54,"Ulnar artery":55,"Common interosseous artery":56,"Superficial palmar arch":57,"Deep palmar arch":58,"Femoral artery":59,"Deep artery of thigh (profunda femoris)":60,"Popliteal artery":61,"Anterior tibial artery":62,"Posterior tibial artery":63,"Fibular (peroneal) artery":64,"Dorsalis pedis artery":65,"Medial plantar artery":66,"Lateral plantar artery":67}
B.aaJ=s(["Begins at the aortic orifice of the left ventricle (aortic valve)."],t.s)
B.a3B=s(["Ends at the sternal angle where it continues as the arch of the aorta."],t.s)
B.a7Y=s(["Runs upward, forward, and to the right within the fibrous pericardium.","Located in the middle mediastinum."],t.s)
B.abM=s(["Right coronary artery.","Left coronary artery."],t.s)
B.a6d=s(["Enclosed by pericardium; related to pulmonary trunk anteriorly/left.","Right atrial appendage lies to its right."],t.s)
B.az0=new A.bz("Ascending aorta",B.aaJ,B.a3B,B.a7Y,B.abM,B.a6d)
B.a2N=s(["Continuation of ascending aorta at the sternal angle (T4/5)."],t.s)
B.a83=s(["Continues as descending thoracic aorta at the level of T4."],t.s)
B.a7N=s(["Arches upward, backward, and to the left over the root of the left lung."],t.s)
B.a2V=s(["Brachiocephalic trunk.","Left common carotid artery.","Left subclavian artery."],t.s)
B.a8C=s(["Left vagus and left phrenic nerves cross it.","Left recurrent laryngeal nerve hooks under the arch near ligamentum arteriosum.","Trachea and esophagus lie posteriorly/medially."],t.s)
B.aya=new A.bz("Arch of aorta",B.a2N,B.a83,B.a7N,B.a2V,B.a8C)
B.abJ=s(["Begins as continuation of the arch of the aorta (T4)."],t.s)
B.a71=s(["Passes through the aortic hiatus (T12) to become the abdominal aorta."],t.s)
B.a7g=s(["Descends in the posterior mediastinum, left of vertebral bodies.","Shifts toward midline as it approaches the diaphragm."],t.s)
B.a5N=s(["Posterior intercostal arteries (3\u201311).","Subcostal artery.","Bronchial arteries.","Esophageal branches.","Pericardial branches.","Superior phrenic arteries."],t.s)
B.aaR=s(["Esophagus lies to its right (variable as it descends).","Thoracic duct is closely related posteriorly."],t.s)
B.ayh=new A.bz("Thoracic aorta",B.abJ,B.a71,B.a7g,B.a5N,B.aaR)
B.a3V=s(["Begins from the right ventricle at the pulmonary valve."],t.s)
B.a6x=s(["Bifurcates into right and left pulmonary arteries at the level of T4/5."],t.s)
B.a4u=s(["Runs upward, backward, and to the left within the pericardium."],t.s)
B.a8l=s(["Right pulmonary artery.","Left pulmonary artery."],t.s)
B.a50=s(["Anterior to the ascending aorta at its origin; then left of it.","Ligamentum arteriosum connects left pulmonary artery to arch of aorta."],t.s)
B.ayv=new A.bz("Pulmonary trunk",B.a3V,B.a6x,B.a4u,B.a8l,B.a50)
B.zh=s(["Begins at bifurcation of the pulmonary trunk."],t.s)
B.a5o=s(["Enters the right lung at the hilum and divides into lobar/segmental branches."],t.s)
B.a9P=s(["Runs horizontally to the right, passing posterior to the ascending aorta and SVC."],t.s)
B.a8o=s(["Lobar arteries to superior, middle, and inferior lobes."],t.s)
B.a7u=s(["At the right hilum, pulmonary artery is anterior to bronchus (RALS: Right Anterior)."],t.s)
B.ayZ=new A.bz("Right pulmonary artery",B.zh,B.a5o,B.a9P,B.a8o,B.a7u)
B.a4b=s(["Enters the left lung at the hilum and divides into lobar/segmental branches."],t.s)
B.ac5=s(["Runs to the left, passing anterior to the descending aorta."],t.s)
B.a4P=s(["Lobar arteries to superior and inferior lobes."],t.s)
B.a74=s(["Ligamentum arteriosum attaches near its origin.","At the left hilum, pulmonary artery is superior to bronchus (RALS: Left Superior)."],t.s)
B.az7=new A.bz("Left pulmonary artery",B.zh,B.a4b,B.ac5,B.a4P,B.a74)
B.ac3=s(["Arises from the right aortic sinus of the ascending aorta."],t.s)
B.a4i=s(["Ends by anastomosing with branches of the left coronary artery in the coronary sulcus (variable)."],t.s)
B.a84=s(["Runs in the right atrioventricular groove (coronary sulcus).","Often reaches the crux of the heart."],t.s)
B.a6O=s(["SA nodal branch (often).","Right marginal artery.","AV nodal branch (often).","Posterior interventricular artery (PDA) in right-dominant circulation."],t.s)
B.a7P=s(["Runs between right atrium and right ventricle in the coronary sulcus."],t.s)
B.ayy=new A.bz("Right coronary artery",B.ac3,B.a4i,B.a84,B.a6O,B.a7P)
B.a5V=s(["Arises from the left aortic sinus of the ascending aorta."],t.s)
B.abU=s(["Typically divides into anterior interventricular (LAD) and circumflex branches."],t.s)
B.a6P=s(["Passes between the left auricle and pulmonary trunk."],t.s)
B.a7a=s(["Anterior interventricular artery (LAD).","Circumflex artery.","Left marginal branch (from circumflex)."],t.s)
B.aai=s(["Close to pulmonary trunk at origin; then in AV groove via circumflex."],t.s)
B.ayk=new A.bz("Left coronary artery",B.a5V,B.abU,B.a6P,B.a7a,B.aai)
B.qu=s(["Arises from the first part of the subclavian artery."],t.s)
B.a6Z=s(["Ends around the 6th intercostal space by dividing into musculophrenic and superior epigastric arteries."],t.s)
B.a5d=s(["Descends posterior to costal cartilages about 1\u20132 cm from the sternum."],t.s)
B.a8L=s(["Anterior intercostal arteries.","Perforating branches.","Musculophrenic artery.","Superior epigastric artery."],t.s)
B.a2Q=s(["Runs parallel to sternum on the posterior aspect of anterior chest wall.","Used commonly as a coronary bypass graft (LIMA)."],t.s)
B.ayq=new A.bz("Internal thoracic artery",B.qu,B.a6Z,B.a5d,B.a8L,B.a2Q)
B.aak=s(["Arise from the thoracic aorta (spaces 3\u201311); first two often from superior intercostal artery."],t.s)
B.a38=s(["Anastomose with anterior intercostal arteries."],t.s)
B.ac2=s(["Run in the costal groove between internal and innermost intercostal muscles."],t.s)
B.a61=s(["Dorsal branches to back.","Collateral branches along superior border of rib below.","Lateral cutaneous branches."],t.s)
B.a7T=s(["Neurovascular bundle order in groove: vein, artery, nerve (VAN) from superior to inferior."],t.s)
B.ayK=new A.bz("Posterior intercostal arteries",B.aak,B.a38,B.ac2,B.a61,B.a7T)
B.zq=s(["Right: from brachiocephalic trunk.","Left: from arch of aorta."],t.s)
B.a2K=s(["Bifurcates at upper border of thyroid cartilage (around C4) into internal and external carotid arteries."],t.s)
B.a4f=s(["Ascends within the carotid sheath."],t.s)
B.a6g=s(["No branches in the neck (typically)."],t.s)
B.abg=s(["In carotid sheath with internal jugular vein (lateral) and vagus nerve (posterior).","Carotid sinus and body at bifurcation."],t.s)
B.ayT=new A.bz("Common carotid artery",B.zq,B.a2K,B.a4f,B.a6g,B.abg)
B.z5=s(["Begins at bifurcation of common carotid artery (C4)."],t.s)
B.a4G=s(["Enters carotid canal in the temporal bone to become petrous part."],t.s)
B.a5A=s(["Ascends in the neck without branching."],t.s)
B.aa5=s(["No branches in the neck."],t.s)
B.a8T=s(["Within carotid sheath; related to pharynx medially."],t.s)
B.ayI=new A.bz("Internal carotid artery (cervical part)",B.z5,B.a4G,B.a5A,B.aa5,B.a8T)
B.a4l=s(["Ends within parotid gland by dividing into maxillary and superficial temporal arteries."],t.s)
B.a6l=s(["Ascends in the neck, passes deep to posterior belly of digastric and stylohyoid, then enters parotid gland."],t.s)
B.a4C=s(["Superior thyroid artery.","Ascending pharyngeal artery.","Lingual artery.","Facial artery.","Occipital artery.","Posterior auricular artery.","Maxillary artery (terminal).","Superficial temporal artery (terminal)."],t.s)
B.a9U=s(["Anterior to internal carotid at origin; crossed by hypoglossal nerve near its start."],t.s)
B.ayV=new A.bz("External carotid artery",B.z5,B.a4l,B.a6l,B.a4C,B.a9U)
